import fs from 'fs';
import os from 'os';
import path from 'path';

export type PendingLogin = {
  sessionId: string;
  pollSecret: string;
  proxyUrl: string;
  createdAt: number;
  generation: string;
  authUrl?: string;
  installRef?: string;
};

const PENDING_LOGIN_TTL_MS = 10 * 60 * 1000;

const pendingLoginPath = (): string =>
  path.join(os.homedir(), '.rivet', 'pending-login.json');

export const writePendingLogin = (pending: PendingLogin): void => {
  const filePath = pendingLoginPath();
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(pending), { mode: 0o600 });
};

export const clearPendingLogin = (): void => {
  try {
    fs.unlinkSync(pendingLoginPath());
  } catch {}
};

export const readPendingLogin = (): PendingLogin | null => {
  let raw: string;
  try {
    raw = fs.readFileSync(pendingLoginPath(), 'utf8');
  } catch {
    return null;
  }
  try {
    const parsed = JSON.parse(raw) as Partial<PendingLogin>;
    if (
      typeof parsed.sessionId !== 'string' ||
      typeof parsed.pollSecret !== 'string' ||
      typeof parsed.proxyUrl !== 'string' ||
      typeof parsed.createdAt !== 'number' ||
      typeof parsed.generation !== 'string' ||
      (parsed.authUrl !== undefined && typeof parsed.authUrl !== 'string') ||
      (parsed.installRef !== undefined &&
        typeof parsed.installRef !== 'string') ||
      Date.now() - parsed.createdAt > PENDING_LOGIN_TTL_MS
    ) {
      clearPendingLogin();
      return null;
    }
    return parsed as PendingLogin;
  } catch {
    clearPendingLogin();
    return null;
  }
};
